        sec5Body = "Remember: Biuret protein test (CuSO₄ + NaOH) and Iodine starch test work COLD (do NOT heat!); ONLY Benedict's/Fehling's reducing sugar test requires boiling in a water bath!",
        sec5Tip = "Never say Bile digests fat chemically—it EMULSIFIES fat mechanically!",
        misc1 = MisconceptionAnalysis("Bile contains a fat-digesting enzyme called lipase.", "Bile acts on fats in the duodenum.", "Bile is enzyme-free! Pancreatic & intestinal LIPASE digest lipids chemically; Bile merely emulsifies large fat globules physically.", "Bile = Mechanical emulsifier + pH alkali neutralizer (0 enzymes)."),
        misc2 = MisconceptionAnalysis("Benedict's reagent detects any sugar including table sugar (sucrose) directly.", "Sucrose is a sugar.", "Sucrose is a non-reducing disaccharide! You MUST boil with HCl then neutralize with NaHCO₃ before Benedict's turns brick-red.", "Check Non-Reducing Sugar hydrolysis rule every time."),
        guidedPrompt = "A student tests cooked yam + groundnut soup extract with (a) Iodine, (b) cold Biuret reagent, and (c) fresh Sucrose solution + cold Benedict's. Predict every colour result and explain how to make Sucrose test positive.",
        guidedHints = listOf(
          "Hint 1: Yam starch → Iodine turns blue-black; Groundnut protein → Biuret turns purple/violet.",
          "Hint 2: Sucrose + cold Benedict's stays sky-blue (stays negative even on gentle heat!).",
          "Hint 3: Boil Sucrose with dil. HCl (hydrolyzes to glucose+fructose), neutralize with NaHCO₃, THEN boil with Benedict's → brick-red!",
        ),
        guidedApproach = "Match each reagent & heat need → apply acid-hydrolysis + neutralization for sucrose.",
        guidedSolution = "(a) Blue-black (yam starch). (b) Violet/purple (groundnut protein). (c) Remains blue (non-reducing & unheated). Boil sucrose with dil. HCl, neutralize with NaHCO₃, re-boil with Benedict's → orange/brick-red!",
        projTitle = "Tracing Digestion of Jollof Rice, Fish & Palm Oil",
        projScenario = "Trace carbohydrates, proteins, and lipids from a plate of Jollof rice and fried fish all the way from mouth to liver/lymph.",
        projStages = listOf("Mouth: Salivary amylase starts starch → maltose.", "Stomach: HCl + Pepsin start fish protein → polypeptides; amylase halts.", "Duodenum/Ileum: Pancreatic enzymes + Bile + Maltase/Erepsin finish → absorption routes."),
        projRubric = listOf("Cites correct pH/enzymes per region.", "Explains bile emulsification clearly.", "Routes glucose/amino acids via Hepatic Portal Vein vs fats via Lacteal."),
        projModel = "Mouth (pH 7): amylase splits rice starch → maltose. Stomach (pH 2): HCl activates pepsinogen → pepsin breaks fish protein → peptides. Duodenum/Ileum (pH 8.5): Bile emulsifies palm oil; pancreatic amylase, trypsin, lipase + maltase/erepsin yield glucose & amino acids (into capillaries → hepatic portal vein) and fatty acids/glycerol (into villus lacteals).",
        cheatOverview = "Starch→Amylase→Maltose→Glucose; Protein→Pepsin/Trypsin→Amino acids; Fat→Bile+Lipase→FA+Glycerol.",
