      "bio_05_transport_circulation" to spec(
        prereq = listOf("bio_02_cells_osmosis", "bio_04_nutrition_digestion"),
        dep = "Double circulation, clotting cascades, and xylem/phloem transport supply O₂ and nutrients to Kidneys, Muscles, and Tissues.",
        vocab = listOf(
          VocabularyEntry("Double Circulation", "Blood visits heart TWICE per full loop: Pulmonary (Heart↔Lungs) + Systemic (Heart↔Body).", "Two pumps bolted side-by-side preventing mixed blood & keeping body pressure high.", "Left Ventricle muscle is 3× thicker than Right Ventricle!"),
          VocabularyEntry("Arteries vs Veins", "Thick-muscled elastic vessels carrying blood AWAY from heart vs thin valved vessels returning TO heart.", "High-pressure firehose vs gentle one-way return pipe.", "Pulmonary ARTERY carries DEOXYGENATED blood; Pulmonary VEIN carries OXYGENATED blood!"),
          VocabularyEntry("Transpiration Stream", "Water pulled UP dead hollow Xylem tubes via root pressure + cohesion-tension evaporation pull.", "Unbroken molecular drinking straw from wet soil to leafy sun.", "High heat, low humidity, and strong wind speed transpiration up!"),
