        ),
        mech1 = "Why do Arteries carry valves ONLY at heart exits while Veins carry pocket valves everywhere? Arteries surge at 120 mmHg systolic squeeze directly from ventricular pumps; Veins trickle at ~5–10 mmHg sluggishly back uphill—needing skeletal muscle squeezes and pocket valves to block backward gravity pooling!",
        mech2 = "Cohesion sticks water molecules tightly to each other while Adhesion sticks them to woody lignin xylem walls; as sun evaporates water off leaf mesophyll, negative tension pulls the entire continuous water column smoothly from taproots up tall Iroko trunks!",
        intel1 = "JAMB tests the 4 blood-vessel exceptions (Pulmonary Artery/Vein & Umbilical Artery/Vein!), heart valve sequence (Tricuspid right, Bicuspid/Mitral left), and potometer leaf-surface petroleum-jelly checks.",
        intel2 = "WAEC Paper 2 checks tree-ringing (girdling) experiments, clotting pathway (Platelets + Ca²⁺ → Thromboplastin → Thrombin → Fibrin mesh), and comparing Open (Insects) vs Closed Single (Fish) vs Closed Double (Mammals) systems.",
        recap1 = "Artery = AWAY from heart; Vein = INTO heart (NEVER define by oxygen alone!).",
        recap2 = "Xylem = Dead upward Water+Minerals; Phloem = Living two-way Organic Sucrose!",
        sec3Title = "3. Clotting Cascade, Fetal Circulation & Transpiration Control",
        sec3Body = "At a skin cut, damaged tissues & platelets + Ca²⁺ convert Prothrombin → Thrombin (requires Vitamin K!), which snips soluble Fibrinogen → insoluble FIBRIN meshwork trapping RBCs into a protective scab. Note Hepatic Portal Vein runs capillary-to-capillary (gut ileum → liver) regulating glucose before general circulation!",
        sec3Formula = "\\text{Prothrombin} \\xrightarrow{\\text{Thromboplastin, Ca}^{2+}} \\text{Thrombin} \\;\\;\\longrightarrow\\;\\; \\text{Fibrinogen} \\xrightarrow{\\text{Thrombin}} \\text{Insoluble Fibrin Clot}",
        sec3Tip = "In root cross-section (dicot), Xylem sits in a central STAR X-shape with Phloem tucked between arms; in stem, Xylem sits INSIDE each ring bundle while Phloem sits OUTSIDE toward bark!",
        sec3Mech = "Outer stem Phloem positioning explains why peeling bark rings off Phloem selectively while sparing deep inner woody Xylem!",
        sec3Intel = "WAEC Paper 3 tests identifying monocot vs dicot root & stem TS diagrams cleanly.",
        sec3Recap = "Dicot stem: Xylem Inside, Phloem Outside (Cambium between); Tree ringing cuts Phloem ONLY.",
        sec4Title = "4. Malaria Sickling RBCs, Blood Donor ABO Compatibility & Drought Wilt",
        sec4Body = "Understanding RBCs (no nucleus, biconcave O₂ carriers), WBCs (lobed nuclei engulfing/antibody immune warriors), and Plasma helps blood banks match safe transfusions (O⁻ universal donor lacks A/B/Rh antigens; AB⁺ universal recipient lacks anti-A/B antibodies!). Farmers mulch soil to curb leaf dehydration wilt during dry Harmattan winds.",
        sec4Tip = "Recipient antibodies attack Donor antigens—NEVER transfuse Group A into Group B!",
        sec5Title = "5. Vessel-Direction & Heart-Side Diagram Trap",
        sec5Body = "Remember anatomical diagrams face YOU like a mirror—the LEFT side of the printed page shows the patient's RIGHT atrium/ventricle (Tricuspid valve), and the RIGHT side of the printed page shows the thick-walled LEFT ventricle (Bicuspid valve → Aorta)!",
        sec5Tip = "Most water leaves via stomata on the LOWER epidermis (underside of dicot leaves)!",
        misc1 = MisconceptionAnalysis("All arteries carry bright red oxygenated blood and all veins carry deoxygenated blood.", "True across legs/arms.", "Arteries carry blood AWAY from heart (so Pulmonary Artery to lungs & Umbilical Artery to placenta carry DEOXYGENATED blood!); Pulmonary Vein & Umbilical Vein carry OXYGENATED blood!", "Always define Artery=AWAY, Vein=TOWARD heart."),
        misc2 = MisconceptionAnalysis("Phloem carries glucose from leaves strictly downward only, while xylem carries water passively up.", "Roots sit below leaves.", "Phloem transports SUCROSE both DOWNWARD to roots AND UPWARD to growing flower buds & young fruits (bi-directional active translocation!).", "Xylem = Strictly upward; Phloem = Two-way."),
        guidedPrompt = "A dicot stem is ringed cleanly all around removing outer bark/phloem down to intact inner xylem. Predict what happens to upper leaves vs lower roots over 3 weeks, and explain why Left Ventricle muscle is far thicker than Right Ventricle.",
        guidedHints = listOf(
          "Hint 1: Inner Xylem remains intact → water still reaches upper leaves (leaves stay green initially!).",
          "Hint 2: Downward sucrose stops above the ring → bark swells into a sugar bulge above cut while roots starve.",
          "Hint 3: Right Ventricle pumps just inches to nearby lungs; Left Ventricle pumps high pressure all the way from head to toes!",
