        guidedApproach = "Separate Xylem (intact) vs Phloem (cut) → compare systemic vs pulmonary distance.",
        guidedSolution = "Leaves stay green temporarily because intact inner xylem supplies water. However, sucrose piles up swelling the bark ring ABOVE the cut while roots starve without sugars, eventually killing the tree. Left Ventricle builds ~6× thicker muscle wall to drive blood across the long high-resistance systemic body circuit.",
        projTitle = "Potometer Humidity/Wind Audit & Blood Bank Clotting Chart",
        projScenario = "Explain why bagging a plant shoot in a plastic bag slows potometer bubble speed almost to zero compared to blowing it with a fan.",
        projStages = listOf("Explain saturated humidity inside the bag flattening water vapour diffusion gradient.", "Contrast fan sweeping humid boundary layer away.", "Check petroleum jelly on lower leaf surface."),
        projRubric = listOf("Links steep vapour gradient to transpiration speed.", "Contrasts bag humid saturation vs dry fan convection.", "Correctly identifies lower epidermis stomatal dominance."),
        projModel = "Trapping transpired moisture inside a clear bag saturates surrounding air (100% RH), collapsing leaf-to-air concentration gradient so potometer bubble stalls. Aiming a fan sweeps humid air away sharply, accelerating bubble speed.",
        cheatOverview = "Heart: RA→RV→Lungs→LA→LV→Body; Xylem=Up Water(dead); Phloem=2-way Sugar(alive).",
        cheatLegend = listOf("Right=Tricuspid", "Left=Bicuspid/Mitral", "Vitamin K+Ca²⁺→Fibrin", "Universal Donor O / Recip AB"),
        cheatTraps = listOf("Defining arteries by O₂", "Confusing left/right on mirror diagram", "Swapping xylem inside/outside in stem"),
        cheatMemory = "Artery=Away; Vein=Visit; Left Thick Systemic; Xylem=Water Up!",
