      "bio_06_respiration_excretion" to spec(
        prereq = listOf("bio_03_photosynthesis_respiration_enzymes", "bio_02_cells_osmosis"),
        dep = "Gas exchange surfaces and kidney ADH osmoregulation anchor Homeostasis alongside Nervous & Endocrine control.",
        vocab = listOf(
          VocabularyEntry("Inhaling Mechanics", "External intercostals contract (ribs UP & OUT), diaphragm contracts/FLATTENS → Volume↑ → Pressure↓ → air rushes in.", "Expanding bellows pulling outside air downward.", "Exhalation relaxes both (diaphragm domes UP), squeezing lungs!"),
          VocabularyEntry("Alveolar Surface Law", "Thin 1-cell wet walls, huge folded area, dense capillary network, steep concentration gradient.", "Fast Fick gas highway shared by gills, alveoli, and earthworm skin.", "CO₂ turns limewater milky; Exhaled air holds 16% O₂ + 4% CO₂ (NOT 0% O₂!)."),
          VocabularyEntry("Ultrafiltration vs Selective Reabsorption", "High Bowman pressure squeezes small molecules out vs PCT active recovery of ALL glucose + useful salts/water.", "Dumping the whole desk drawer out then putting valuables carefully back!", "Healthy urine contains ZERO glucose and ZERO proteins!"),
          VocabularyEntry("ADH (Antidiuretic Hormone)", "Pituitary hormone making collecting ducts MORE permeable to water when blood is dehydrated.", "Sponge-save hormone concentrating dark small urine.", "Drinking tons of water drops ADH → large pale dilute urine!"),
        ),
        mech1 = "Why are Kidney glomeruli coiled tighter with a WIDER incoming afferent arteriole than narrow outgoing efferent arteriole? That bottleneck builds intense ~70 mmHg hydraulic pressure pushing water, urea, glucose, and salts through Bowman's basement filter while leaving large blood cells & proteins safely behind in blood!",
        mech2 = "Plants excrete far simpler than animals because photosynthesis recycles CO₂ into glucose and O₂ becomes plant waste—while excess gums, resins, tannins, and Ca-oxalate crystals store harmlessly in falling bark, dead heartwood, and shed yellow leaves!",
        intel1 = "JAMB tests matching organisms to excretory organs (Flatworm→Flame cell; Earthworm→Nephridia; Insect→Malpighian tubule; Vertebrate→Kidney!), Loop of Henle concentration gradients, and diabetic glycosuria diagnosis.",
        intel2 = "WAEC Paper 2 tests bell-jar rubber-sheet diaphragm model mechanics AND tracing urine pathway Kidney→Ureter→Bladder→Urethra.",
        recap1 = "Inhale = Diaphragm FLATTENS down, Ribs UP/OUT, Lung Pressure DROPS below atmosphere!",
        recap2 = "Bowman filtrate holds Glucose (0% protein); Healthy final Urine holds 0% Glucose & 0% Protein!",
        sec3Title = "3. Invertebrate Excretory Organs, Skin Thermoregulation & Liver",
        sec3Body = "Know comparative organs: Protozoa → Contractile Vacuole (osmoregulation!); Platyhelminthes → Flame Cells; Annelids → Nephridia; Insects → Malpighian Tubules (uric acid crystals save water!); Crustaceans → Green glands; Vertebrates → Kidneys. In Liver: deamination strips toxic −NH₂ off excess amino acids → Ammonia → safe UREA via Ornithine cycle!",
        sec3Formula = "\\text{Excess Amino Acids} \\xrightarrow{\\text{Liver Deamination}} \\text{NH}_3 + \\text{CO}_2 \\rightarrow \\text{Urea (excreted)} + \\text{Carbohydrate}",
        sec3Tip = "Hot Nigerian afternoon skin cooling: Arterioles VASODILATE (more blood to surface), sweat glands secrete water evaporating via latent heat, hair erector muscles RELAX flat!",
        sec3Mech = "During Harmattan cold mornings, arterioles VASOCONSTRICT (keep warm blood deep inside core), shivering muscles generate metabolic heat, and hairs raise insulation.",
        sec3Intel = "WAEC/NECO penalize saying capillaries 'move up toward the skin'—only ARTERIOLES widen/narrow diameter (vasodilation/vasoconstriction)!",
        sec3Recap = "Hot → Vasodilate + Sweat; Cold → Vasoconstrict + Shiver.",
        sec4Title = "4. Harmattan Dehydration, Malaria Kidney Checks & Dialysis",
        sec4Body = "In hot dry Harmattan afternoons, high sweat loss thickens blood osmolarity → Hypothalamus triggers Pituitary ADH release → nephrons salvage maximum water, outputting dark low-volume urine! Hospital dialysis machines diffuse excess urea across semi-permeable tubing bathing in clean glucose-matched dialysate so patients don't lose vital blood sugar.",
        sec4Tip = "Kidney stone crystals, proteinuria, or sugar in urine warn instantly of nephron damage or diabetes mellitus!",
        sec5Title = "5. Diaphragm Shape & Dialysate Composition Check",
        sec5Body = "Remember: Diaphragm is DOME-SHAPED when relaxed (Exhale) and FLATTENED when contracted (Inhale)—students frequently flip that! Also never say urea is MADE inside the kidney: urea is MADE inside the LIVER by deamination and FILTERED OUT by the Kidney!",
        sec5Tip = "Exhaled air STILL contains ~16% O₂ (that's why mouth-to-mouth CPR revives people!).",
        misc1 = MisconceptionAnalysis("Urea is manufactured inside the kidneys out of urine.", "Kidneys excrete urea.", "Toxic ammonia from excess dietary proteins is converted into safe UREA inside the LIVER (deamination), carried in blood, and merely FILTERED OUT by the Kidneys!", "Liver MAKES urea; Kidneys EXCRETE urea."),
        misc2 = MisconceptionAnalysis("During inhalation, the diaphragm rises upward into a tight dome pushing air in.", "Rising chest = rising diaphragm.", "Expanding the chest cavity pulls the floor DOWN: diaphragm CONTRACTS and FLATTENS downward while ribs pull UP and OUT!", "Inhale = Volume UP (Diaphragm DOWN + Ribs UP)."),
        guidedPrompt = "Compare composition of Blood Plasma, Glomerular Filtrate in Bowman's capsule, and Healthy Urine for (1) Plasma Protein, (2) Glucose, and (3) Urea, explaining why each shifts.",
        guidedHints = listOf(
          "Hint 1: Plasma proteins are too large to cross Bowman's glomerulus → Present in Plasma ONLY (0% in Filtrate & Urine).",
          "Hint 2: Small Glucose filters freely into Bowman's capsule, then 100% is actively reabsorbed at PCT → Present in Plasma & Filtrate, 0% in Healthy Urine!",
          "Hint 3: Urea filters freely and water is reabsorbed down the tubule → Urea is ~60× MORE concentrated in Urine!",
