        projTitle = "Dialysis Fluid Formulation & Harmattan Hydration Brief",
        projScenario = "Design ideal Dialysis Fluid concentrations for Urea, Glucose, and Na⁺ relative to normal blood plasma so kidney failure patients clear toxins safely without shock.",
        projStages = listOf("Set Urea = 0 mg/dL (steep outward diffusion gradient).", "Set Glucose & normal Na⁺ = Exact healthy plasma concentration.", "Explain why blood and dialysate flow in COUNTER-CURRENT directions."),
        projRubric = listOf("Zero urea in dialysate.", "Isotonic glucose/ions prevent nutrient loss.", "Explains counter-current maintains concentration gradient continuously."),
        projModel = "Dialysate contains 0 urea (so blood urea diffuses down steep gradient into bath continuously), exact normal blood glucose (~90 mg/dL) and electrolytes (so vital nutrients don't diffuse away), flowing counter-current to maximize toxin removal across the whole membrane.",
        cheatOverview = "Inhale: Diaph Flat/Down + Ribs Up/Out; Nephron: Filter→Reabsorb Glucose(PCT)→ADH Water(CD).",
