          VocabularyEntry("Inner Ear Cochlea vs Semicircular", "Spiral fluid Cochlea transduces pitch/sound via Organ of Corti; Semicircular canals + utriculus sense BALANCE & head rotation!", "Hearing snail vs 3D balance spirit-level.", "Ossicles (Malleus→Incus→Stapes) amplify eardrum vibrations ~20× onto oval window!"),
        ),
        mech1 = "Why does reading a tiny textbook strain your eyes far more than gazing out over distant hills? Looking far away RELAXES ciliary muscles cleanly—whereas focusing 25 cm close forces circular ciliary muscles to contract tight continuously, slackening suspensory ligaments so the lens rounds fat!",
        mech2 = "In dim light, RADIAL iris muscles contract pulling pupil wide open; in bright noon glare, CIRCULAR iris muscles contract squeezing pupil tiny to protect delicate rod/cone photoreceptors (Rods = dim B&W using rhodopsin/Vit A; Cones = bright colour!).",
        intel1 = "JAMB tests dorsal (sensory + ganglion!) vs ventral (motor!) spinal roots, brain centres (Cerebellum=balance/posture; Medulla=breathing/heartbeat; Hypothalamus=temp/osmoregulation; Cerebrum=memory/intelligence), and Myopia vs Hypermetropia lens fixes.",
        intel2 = "WAEC Paper 2 checks labelling vertical Eye & Ear sections cleanly and contrasting Voluntary vs Reflex actions.",
        recap1 = "NEAR sight = Ciliary CONTRACT, Ligaments SLACK, Lens FATTER; FAR = Ciliary RELAX, Ligaments TAUT, Lens THIN.",
        recap2 = "Cerebellum = Motor balance; Medulla oblongata = Involuntary breathing/heartbeat; Cerebrum = Conscious thought.",
        sec3Title = "3. Brain Lobes, Spinal Dorsal/Ventral Roots & Eye/Ear Defects",
        sec3Body = "Spinal cross-section H-shaped Grey matter contains cell bodies inside, surrounded by myelinated White matter outside! Sensory neurones enter via DORSAL root (note swelling Dorsal Root Ganglion!); Motor neurones exit via VENTRAL root. Eye: Myopia focuses ahead of retina → Concave (−) lens; Hypermetropia behind retina → Convex (+) lens; Astigmatism uneven cornea → Cylindrical lens!",
        sec3Formula = "\\text{Stimulus} \\rightarrow \\text{Receptor} \\rightarrow \\text{Sensory} \\xrightarrow{\\text{Dorsal}} \\text{Relay (Grey Matter)} \\xrightarrow{\\text{Ventral}} \\text{Motor} \\rightarrow \\text{Effector}",
        sec3Tip = "Semicircular canals detect rotational movement/balance—NEVER sound hearing (Cochlea handles hearing)!",
        sec3Mech = "Three perpendicular semicircular tubes sit at 90° matching X-Y-Z axes so endolymph fluid lag bends hair cells in any spin direction.",
        sec3Intel = "NECO/JAMB love testing Dorsal vs Ventral spinal root lesion loss (cut Dorsal = feel nothing, still move; cut Ventral = feel touch, paralyzed!).",
        sec3Recap = "Dorsal = In (Sensory + Ganglion); Ventral = Out (Motor).",
        sec4Title = "4. Hot-Pot Reflex, Harmattan Eustachian Popping & Road Vision",
        sec4Body = "Swallowing during an Abuja–Lagos flight descent opens the Eustachian tube linking middle ear to pharynx so cabin pressure equalizes gently across your eardrum! Night drivers lacking Vitamin A lose retinal rhodopsin regeneration, triggering night blindness.",
        sec4Tip = "Eustachian tube balances air pressure equally on BOTH sides of the eardrum!",
        sec5Title = "5. Ciliary vs Suspensory Opposites & Brain Centre Check",
        sec5Body = "Drill the Eye Accommodation rule: Ciliary Muscle and Suspensory Ligaments ALWAYS act OPPOSITELY! Contract ciliary = Slack ligament = Fat lens (Near). Relax ciliary = Tight pulled ligament = Flat thin lens (Far).",
        sec5Tip = "Myelin sheath insulates axons to speed saltatory nerve conduction (~100 m/s)!",
        misc1 = MisconceptionAnalysis("Reading close up stretches the eye lens tight with taut suspensory ligaments.", "Close focus feels tense.", "Actually, tightening suspensory ligaments pulls the lens FLAT for FAR view! Reading NEAR contracts circular ciliary muscle inward, SLACKENING ligaments so the elastic lens bulges FAT!", "Near = Ciliary Contract + Ligament Slack + Fat Lens."),
        misc2 = MisconceptionAnalysis("All 3 parts of the inner ear (cochlea & semicircular canals) help us hear sound.", "Both sit inside the inner ear.", "Cochlea = Hearing; Semicircular canals + Sacculus/Utriculus = Dynamic & Static Balance!", "Spin dizziness comes from semicircular fluid momentum, not cochlea."),
        guidedPrompt = "Compare what happens inside a student's eye when shifting gaze from a distant billboard to reading small print on a phone, and identify which spinal root carries motor impulses to arm muscles.",
        guidedHints = listOf(
          "Hint 1: Shifting Far → Near requires stronger bending power (fatter convex lens).",
          "Hint 2: Circular ciliary muscles CONTRACT → suspensory ligaments SLACKEN → elastic lens bulges MORE convex.",
          "Hint 3: Motor axons exit the spinal cord exclusively via the VENTRAL root (no dorsal ganglion!).",
        ),
        guidedApproach = "State ciliary/ligament/lens triad → identify Ventral motor root.",
        guidedSolution = "Ciliary muscles contract inward, suspensory ligaments go slack, and elastic lens rounds fatter/more convex to focus near text cleanly onto fovea. Motor impulses exit via the VENTRAL root.",
