        projScenario = "Design a patient diagnostic summary separating Myopia, Hypermetropia, Astigmatism, and Eustachian-tube ear block.",
        projStages = listOf("Match eyeball focus error to exact corrective lens shape.", "Explain ossicle sound amplification vs Eustachian air balance.", "Contrast Cerebellum vs Cochlea vs Medulla deficits."),
